"""Reactor implementations."""

import functools
import inspect
import itertools
import logging
import typing

from jsilib import _utils
from jsilib._compat import asyncio
from jsilib.aio.interface import Event, ITask

from . import _globals
from .interface import EventListener, IReactor, T

__all__ = export = _utils.ExportList()

logger = logging.getLogger(_globals.LOGGER_NAME)


@export
class Reactor(IReactor):

    def __init__(self, event_loop: asyncio.AbstractEventLoop = None):

        @_utils.log_exceptions(logger)
        async def event_dispatcher():

            @_utils.log_exceptions(logger)
            async def listener_caller(listener, event):
                if inspect.iscoroutinefunction(listener):
                    return await listener(event)
                return listener(event)

            while True:
                event = await self._event_queue.get()
                listeners = [x for x in self._event_listeners.get(event.__class__, {}).values()]
                logger.debug('Notifying total number of %d listeners with event: %r', len(listeners), event)
                await asyncio.gather(*[listener_caller(listener, event) for listener in listeners])

        self._event_loop = event_loop or asyncio.get_event_loop()
        self._closed = False
        self._tasks_running: typing.Dict[int, ITask] = {}
        self._handles_running: typing.Dict[int, asyncio.Handle] = {}
        self._listener_id = itertools.count(1)
        self._task_id = itertools.count(1)
        self._event_listeners = {}
        self._event_queue: asyncio.Queue[Event] = asyncio.Queue()

        self.run(event_dispatcher())

    @property
    def event_loop(self) -> asyncio.AbstractEventLoop:
        return self._event_loop

    def is_closed(self) -> bool:
        return self._closed

    async def close(self):
        if self._closed:
            return
        self._closed = True
        for task in dict(self._tasks_running).values():
            if task is not None:
                await task.cancel()
        for task in dict(self._handles_running).values():
            task.cancel()

    def call_soon(self, func: typing.Callable, *args, **kwargs) -> int:

        @_utils.log_exceptions(logger)
        def func_wrapper():
            try:
                func(*args, **kwargs)
            finally:
                del self._handles_running[task_id]

        task_id = _utils.next_unique_id()
        self._handles_running[task_id] = self._event_loop.call_soon(func_wrapper)
        return task_id

    def call_later(self, delay: float, func: typing.Callable, *args, **kwargs) -> int:

        @_utils.log_exceptions(logger)
        def func_wrapper():
            try:
                func(*args, **kwargs)
            finally:
                del self._handles_running[task_id]

        task_id = _utils.next_unique_id()
        self._handles_running[task_id] = self._event_loop.call_later(delay, func_wrapper)
        return task_id

    def cancel(self, task_id: int) -> bool:
        handle = self._handles_running.pop(task_id, None)
        if handle is not None:
            handle.cancel()
            return True
        return False

    def notify(self, event: Event):
        self._event_queue.put_nowait(event)

    def subscribe(self, listener: EventListener, event_type: typing.Type[Event]) -> int:
        listener_id = next(self._listener_id)
        self._event_listeners.setdefault(event_type, {})[listener_id] = listener
        logger.debug(
            'Event listener subscribed: listener=%r, event_type=%r (id: %d)', listener, event_type, listener_id
        )
        return listener_id

    def unsubscribe(self, listener_id: int) -> bool:
        for listeners in self._event_listeners.values():
            if listener_id in listeners:
                del listeners[listener_id]
                logger.debug('Event listener unsubscribed (id: %d)', listener_id)
                return True
        return False

    async def run_blocking(self, func: typing.Callable[[], T], *args, **kwargs) -> T:
        return await self.event_loop.run_in_executor(None, functools.partial(func, *args, **kwargs))

    def run(self, coroutine: typing.Coroutine) -> ITask:
        task_id = next(self._task_id)
        task_wrapper = self._TaskWrapper(self, task_id)
        task_wrapper._bind_target(self._event_loop.create_task(coroutine))
        return task_wrapper

    class _TaskWrapper(ITask):

        def __init__(self, creator: 'Reactor', task_id: int):
            self._target = None
            self._creator = creator
            self._task_id = task_id

        def __repr__(self) -> str:
            return repr(self._target)

        def _bind_target(self, target: asyncio.Task):
            self._target = target
            self._creator._tasks_running[self._task_id] = self

        def name(self) -> str:
            return self._target.get_name()

        def done(self) -> bool:
            return self._target.done()

        def cancel_nowait(self):
            return self._target.cancel()

        async def cancel(self):
            self.cancel_nowait()
            try:
                await self
            except asyncio.CancelledError:
                pass

        def result(self) -> typing.Any:
            return self._target.result()

        def __await__(self):
            try:
                yield from self._target
            except asyncio.CancelledError:
                raise
            except Exception:
                raise
            finally:
                self._creator._tasks_running.pop(self._task_id, None)
